  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'Тоглуулах, сэтгэгдэл бичих, таалагдах, дараа үзэх, захиалга, мэдэгдэл, мессеж, тоглуулах жагсаалт болон хэлний тохиргоог үндсэн навигаци болон бүртгэлийн цэсээр дамжуулан авах боломжтой.',
  'PlayHub' => 'PlayHub',
