  'The configured' => 'Тохируулсан',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'Хөгжүүлэгчийн хуудас нь шууд Laravel backend-тэй холбогдсон: чиглүүлэлтийн бүртгэл, мэдээллийн сангийн тоо, байршуулах хязгаарлалт, платформын мета өгөгдлийг /api/developers-ээс ачаалдаг.',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'Фронт хэсэг нь сонгосон хэл, сэдэв, тоглуулах дараалал, үзэх явц, интерфэйсийн төлөв зэрэг тохиргоог хадгалдаг тул хуудасны навигаци болон дахин ачааллахад тогтвортой байх болно.',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'Боловсруулах ажил нь орчуулгыг кодлож, шаардлагатай үед өнгөц зургийг үүсгэж, тайлбарыг хадгалж, боловсруулалт дуусахад видео бэлэн болсон гэж тэмдэглэдэг. Ирээдүйд төлөвлөсөн видеонууд нь хуваарь гаргагч тэднийг гаргах хүртэл хувийн хэвээр үлдэнэ.',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'Байршуулах систем нь өгөгдлийн санд тулгуурласан, API-аас ангилал, хэлийг дэмждэг, байршуулсан видеог боловсруулдаг, өнгөц зураг, тайлбарыг хадгалдаг, хуваарьтай контентыг гарах хүртэл нь нууцалдаг.',
