  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'Шууд PlayHub датагаар байршуулах, үзэх, бүртгүүлэх, зохицуулах, бүтээх.',
  'Uploaded videos' => 'Байршуулсан видеонууд',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'Байршуулсан видеонуудыг тоглуулах боломжтой хувилбар болгон кодчилдог. Боловсруулах хугацаа нь файлын хэмжээ, үргэлжлэх хугацаа, серверийн ачаалал, дарааллын төлөвөөс хамаарна. Байршуулах хуудас болон Бүтээгчийн студи нь видео бичлэгийн боловсруулалтын бодит байдлыг харуулдаг.',
  'Uploads, scheduling, and processing are available.' => 'Байршуулах, хуваарь гаргах, боловсруулах боломжтой.',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => 'Зохиогчийн ажлын урсгалд /api/videos, сувгийн төгсгөлийн цэгүүд болон баталгаажуулсан маршрутуудыг ашиглана уу.',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'Админууд яг агуулгын лавлагааг хүлээн авахын тулд видео болон сэтгэгдлүүдэд зориулсан тайлангийн үйлдлийг ашиглана уу. Админ самбарын хуудсууд нь хэрэглэгчид, контент, тайлан, мөнгө олох арга, аналитик, дэмжлэг, үүрэг, системийн тохиргоо зэрэгт шууд мэдээллийн сангийн өгөгдлийг ашигладаг.',
  'Use Contact Us' => 'Бидэнтэй холбоо барина уу',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'Ердийн API хүсэлтэд JSON, файл байршуулахад FormData ашиглана уу. Баталгаажуулалтыг алгасаж болохгүй: категори болон хэлүүд нь мэдээллийн баазын ID, харагдац нь нийтийн, жагсаалтаас гадуур эсвэл хувийн байдлаар хязгаарлагддаг бөгөөд тайлбар нь SRT, VTT эсвэл TXT файлуудыг хүлээн зөвшөөрдөг.',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'Профайл, аюулгүй байдал, нууц үг, хоёр хүчин зүйлийн хүргэлт, төхөөрөмж, сонголт, мэдэгдлийн сонголтуудыг шинэчлэхийн тулд Тохиргоог ашиглана уу. Хэрэв та өөрийн акаунтад нэвтэрч чадахгүй бол нэвтрэх урсгалыг ашиглан сайтын админд дансны имэйл хаягаа оруулна уу.',
  'Use the contact form' => 'Холбоо барих маягтыг ашиглана уу',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'Админууд яг агуулгын лавлагааг хүлээн авахын тулд видео, сэтгэгдэл, олон нийтийн нийтлэл дээр тайлангийн үйлдлүүдийг ашиглана уу.',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'Агуулга нь платформын дүрмийг зөрчиж болзошгүй үед видео, сэтгэгдэл, олон нийтийн нийтлэлд тайлангийн үйлдлийг ашиглана уу. Эдгээр тайлангууд нь бодит агуулгын бүртгэлтэй холбоотой бөгөөд администраторууд яг тухайн зүйлийг шалгаж үзэх боломжтой тул ерөнхий мессежээс илүү сайн байдаг.',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'Бүртгэлийн тусламж, агуулгын тайлан, техникийн асуудал болон администраторын хүсэлтийн талаар зөв PlayHub сувгийг ашиглана уу.',
  'Video categories' => 'Видео ангилал',
  'Video for everyone. Built for creators and viewers.' => 'Хүн бүрт зориулсан видео. Бодит платформ өгөгдлөөр бүтээгдсэн.',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'Видео байршуулах, хуваарь гаргах, өнгөц зураг, боловсруулахтай холбоотой асуудлууд.',
  'Videos, thumbnails, captions, processing.' => 'Видео, өнгөц зураг, тайлбар, боловсруулалт.',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'Үзэгчид ангилал үзэх, видео хайх, контент үзэх, сувагт бүртгүүлэх, дараа үзэхийн тулд видео хадгалах, сэтгэгдэл бичих, мэдэгдэл хүлээн авах, хэл болон хандалтын тохиргоог удирдах боломжтой.',
  'Viewing and community help' => 'Үзэх, олон нийтийн тусламж',
  'Waiting for backend endpoint inventory.' => 'Арын төгсгөлийн цэгийн тооллогыг хүлээж байна.',
  'We’re here to help.' => 'Бид туслахаар ирлээ.',
  'What is PlayHub?' => 'PlayHub гэж юу вэ?',
  'What PlayHub does' => 'PlayHub юу хийдэг вэ',
  'Where do contact messages go?' => 'Холбоо барих мессежүүд хаашаа явдаг вэ?',
  'Why is my video still processing?' => 'Яагаад миний видеог боловсруулж байна вэ?',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'Тиймээ. Байршуулах хуудсан дээрх үндсэн хуваарийн огноо, цагийн талбарыг ашиглана уу. Backend нь scheduled_at-г хадгалж, видеог боловсруулж, огноог ирээдүйд байх үед нууцалж, Laravel хуваарьлагч төлөвлөсөн цагаас хойш ажиллах үед үүнийг гаргадаг.',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'Тиймээ. Байршуулах дээр үндсэн хуваарийн талбарыг ашиглана уу. Backend нь scheduled_at-г хадгалж, хуваарийн цагт хүрсэн үед боловсруулсны дараа видеог гаргадаг.',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'Та зочны хувиар үзэж байна. Бүртгэлд зориулсан хэрэгслүүдэд хандахын тулд нэвтэрнэ үү.',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'Та өөрийн бүртгэлийн итгэмжлэл, профайлын үйл ажиллагаа, байршуулсан контент, сэтгэгдэл, мессеж болон таны бүртгэлээс хийсэн бүтээгч эсвэл админы үйлдлийг хариуцна. Хүчтэй нууц үг хэрэглэж, хоёр хүчин зүйлтэй хүргэх аргуудыг шинэчлээрэй.',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'Та хөтчийн тохиргооноос хөтчийн күүкиг болон дотоод санах ойг цэвэрлэх боломжтой. Чухал хадгалах санг арилгах нь таныг гарах, хэл/загварын тохиргоог дахин тохируулах, локал тоглуулах төлөвийг устгах, дахин нэвтрэхийг шаардаж болзошгүй.',
  'You receive a response by email.' => 'Та имэйлээр хариу хүлээн авна.',
  'You’re in control' => 'Та хяналтанд байна',
  'Your choices' => 'Таны сонголтууд',
  'Your message is saved directly in the website backend and appears in the admin dashboard under Support.' => 'Таны мессежийг вэбсайтын арын хэсэгт шууд хадгалах бөгөөд "Дэмжлэг" хэсэгт байрлах админ самбарт харагдана.',
  'Your support' => 'Таны дэмжлэг',
