  'Use Shorts for discovery' => 'Богино өмд ашигла',
  'Keep testing quick hooks and link viewers to longer videos.' => 'Түргэн дэгээг туршиж үзээд үзэгчдэд илүү урт видеонуудыг холбоно уу.',
