  'Start a new upload with titles, tags, visibility, and thumbnail steps.' => 'Гарчиг, шошго, харагдац, өнгөц зургийн алхмуудыг агуулсан шинэ байршуулалтыг эхлүүлээрэй.',
  'Shorts studio' => 'Богино өмдний студи',
